mapper.select:
SELECT 
FROM meetups m
WHERE m.id = #{id}

mapper.update:
UPDATE meetups
SET status = #{status},
    reject_reason = #{rejectReason},
    review_note = #{reviewNote},
    reviewed_by = #{reviewedBy},
    reviewed_at = #{now},
    data_version = data_version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = 'PENDING_REVIEW'
  AND visible_until > #{now}
  AND data_version = #{expectedVersion}

UPDATE meetups
SET status = 'WITHDRAWN',
    data_version = data_version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND host_user_id = #{hostUserId}
  AND status = 'PENDING_REVIEW'

UPDATE meetups
SET status = 'CANCELLED',
    cancel_reason = #{reason},
    cancelled_at = #{now},
    data_version = data_version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND host_user_id = #{hostUserId}
  AND status = 'APPROVED'
  AND visible_until > #{now}

mapper.sql:
WHERE m.status = 'APPROVED'
  AND m.visible_until > #{p.now}
  AND m.display_latitude BETWEEN #{p.minLat} AND #{p.maxLat}
  AND m.display_longitude BETWEEN #{p.minLng} AND #{p.maxLng}
  AND (
    6371 * acos(
        LEAST(1.0, GREATEST(-1.0,
            cos(radians(#{p.latitude})) * cos(radians(m.display_latitude)) *
            cos(radians(m.display_longitude) - radians(#{p.longitude})) +
            sin(radians(#{p.latitude})) * sin(radians(m.display_latitude))
        ))
    )
  ) <= #{p.radiusKm}

  AND m.category IN

        #{category}


  AND 
  AND NOT EXISTS (
    SELECT 1 FROM user_blocks b
    WHERE (b.blocker_id = #{p.viewerId} AND b.blocked_id = m.host_user_id)
       OR (b.blocker_id = m.host_user_id AND b.blocked_id = #{p.viewerId})
  )

