SELECT 
FROM meetups m
WHERE m.host_user_id = #{hostUserId}
ORDER BY m.created_at DESC, m.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM meetups m
WHERE m.host_user_id = #{hostUserId}
  AND m.status IN ('PENDING_REVIEW', 'APPROVED')
  AND m.visible_until > #{now}

  AND m.id <> #{excludeId}

SELECT COUNT(*)
FROM meetups m
WHERE m.host_user_id = #{hostUserId}
  AND m.submitted_at > #{since}

